package tr.gov.kocaeli.sehir.document.api;
import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import org.springframework.web.multipart.MultipartFile;import tr.gov.kocaeli.sehir.document.application.DocumentService;import java.nio.charset.StandardCharsets;import java.util.*;
@RestController @RequestMapping("/api/v1/documents")public class DocumentController{private final DocumentService service;public DocumentController(DocumentService service){this.service=service;}@PostMapping(consumes=MediaType.MULTIPART_FORM_DATA_VALUE)Map<String,Object>upload(@RequestParam String subjectType,@RequestParam UUID subjectId,@RequestParam String documentType,@RequestParam(required=false)String description,@RequestPart MultipartFile file){return service.upload(subjectType,subjectId,documentType,description,file);}@GetMapping("/{id}/content")ResponseEntity<byte[]>download(@PathVariable UUID id){var d=service.download(id);var cd=ContentDisposition.attachment().filename(d.filename(),StandardCharsets.UTF_8).build();return ResponseEntity.ok().contentType(MediaType.parseMediaType(d.mimeType())).header(HttpHeaders.CONTENT_DISPOSITION,cd.toString()).body(d.bytes());}}
